<?php
function ns_recovery_batch($b){return $b['import_type']==='Non-Sellable Release'&&($b['workflow']['data']['type']??'')==='Return to Sellable';}
function ns_recovery_source($id,$lock=false){$q=om_query('SELECT n.*,p.master_sku,p.name FROM non_sellable n JOIN products p ON p.id=n.product_id WHERE n.id=?'.($lock?' FOR UPDATE':''),[(int)$id]);$r=$q->fetch();if(!$r||$r['reversed_by_request']!==null||packaging_kind($r['condition_type'])!=='damaged'||studio_source($r))throw new Exception('Select an active Damaged / Leak source.');wc_ns_guard($r['id']);$r['remaining']=max(0,(int)$r['qty']-release_total($r['id']));if(!$r['remaining'])throw new Exception('No remaining quantity can be returned to Sellable.');return $r;}
function ns_recovery_page(){
 if(!can_action('nonsellable_out')){echo '<p class="alert warn">Transaction access is required. CSR viewing remains read only.</p>';return;}
 $editId=(int)($_GET['editing_id']??0);$edit=$editId?workflow_batch($editId):null;$initial=[];if($edit){workflow_owner($edit);if(!ns_recovery_batch($edit)||$edit['status']!=='Review')throw new Exception('Only an unsubmitted Return to Sellable draft can be edited.');$initial=$edit['workflow']['data'];} $r=ns_recovery_source($edit?(int)$initial['items'][0]['source_id']:(int)($_GET['source_id']??0));$s=stock_row($r['product_id']);$dest=in_array($r['platform'],['Shopee','Lazada','TikTok','Website'],true)?$r['platform']:'Shopee';$dest=$initial['destination_platform']??$dest;
 echo '<div class="page-head"><div><a class="back" href="?page=nonsellable&amp;stock_view=damaged">← Damaged / Leak</a><h1>Return to Sellable</h1><p>Use only after inspection confirms the actual item is complete and fit for sale.</p></div></div><section class="card"><h3>'.e($r['name']).'</h3><p class="muted">'.e($r['master_sku'].' · NS-'.$r['id'].' · '.$r['order_id']).'</p><p>Remaining at source: <strong>'.$r['remaining'].' pcs</strong> · Total physical: '.$s['physical'].' pcs</p><form method="post" action="actions.php" class="stack">';workflow_hidden('batch_prepare',['kind'=>'Non-Sellable Release','type'=>'Return to Sellable','reference_no'=>$initial['ref']??next_ref('REC'),'editing_batch_id'=>$editId,'editing_digest'=>$edit['workflow']['digest']??'','batch_nonce'=>bin2hex(random_bytes(16)),'items[0][source_id]'=>$r['id'],'return'=>'nonsellable&stock_view=damaged']);
 echo '<div class="grid two"><label>Date<input type="date" name="txn_date" value="'.e($initial['txn_date']??date('Y-m-d')).'" min="'.e($r['txn_date']).'" max="'.date('Y-m-d').'" required></label><label>Quantity<input type="number" name="items[0][qty]" value="'.e($initial['items'][0]['qty']??'').'" min="1" max="'.$r['remaining'].'" step="1" required></label><label>Destination Platform<select name="destination_platform">';foreach(['Shopee','Lazada','TikTok','Website'] as $pl)echo '<option '.($pl===$dest?'selected':'').'>'.e($pl).'</option>';echo '</select></label><label>Inspection / Recovery Reason<textarea name="reason" rows="2" minlength="3" maxlength="2000" required>'.e($initial['reason']??'').'</textarea></label></div><label class="ack"><input type="checkbox" name="inspection_ack" value="1" required> I inspected these actual units. They are complete, functional and fit for sale; no component is missing.</label><p class="muted small">After approval: Non-Sellable − quantity; Sellable + quantity. Total Physical stays unchanged. The original damaged receipt stays in history.</p><div class="modal-actions"><a class="btn ghost" href="?page=nonsellable&amp;stock_view=damaged">Cancel</a><button class="btn primary">Review Return to Sellable</button></div></form></section>';
}
function ns_recovery_post($data,$line,$batchId){
 $r=ns_recovery_source($line['source_id'],true);$pid=(int)$r['product_id'];$qty=(int)$line['qty'];check_platform_alignment($pid);$before=stock_row($pid);if($qty>$r['remaining']||$qty>$before['nonsellable'])throw new Exception('Return quantity exceeds remaining source or Non-Sellable stock.');$date=$data['txn_date'];$reason=$data['reason'].'; Recovery request #'.$batchId.'; '.$data['ref'];$ref='REC-'.$batchId.'-'.$r['id'];$uid=current_user()['id'];$destination=stock_platform($data['destination_platform']);
 if(om_query('SELECT id FROM packaging_completions WHERE completion_ref=?',[$ref])->fetchColumn())throw new Exception('This reclassification is already posted.');
 om_query('INSERT INTO nonsellable_outflows(txn_date,product_id,qty,type,reference_no,remarks,user_id) VALUES(?,?,?,?,?,?,?)',[$date,$pid,$qty,'Ready for Sale',$ref,$reason,$uid]);$release=(int)db()->lastInsertId();om_query('INSERT INTO nonsellable_release_links(release_id,non_sellable_id,qty) VALUES(?,?,?)',[$release,$r['id'],$qty]);
 om_query('INSERT INTO inflows(txn_date,reference_no,source_name,product_id,source_qty,source_uom,qty,type,remarks,user_id) VALUES(?,?,?,?,?,?,?,?,?,?)',[$date,$ref,'NS-'.$r['id'],$pid,$qty,'pc',$qty,'Ready for Sale',$reason,$uid]);$inflow=(int)db()->lastInsertId();$allocation=array_fill_keys(['Shopee','Lazada','TikTok','Website'],0);$allocation[$destination]=$qty;change_platform_stock($destination,$pid,$qty,$ref,$date);
 om_query('INSERT INTO packaging_completions(completion_ref,source_id,product_id,qty,txn_date,inflow_id,release_id,allocation_json,reason,user_id) VALUES(?,?,?,?,?,?,?,?,?,?)',[$ref,$r['id'],$pid,$qty,$date,$inflow,$release,json_encode($allocation),$reason,$uid]);$completion=(int)db()->lastInsertId();check_platform_alignment($pid);$after=stock_row($pid);if($after['physical']!==$before['physical']||$after['current']!==$before['current']+$qty||$after['nonsellable']!==$before['nonsellable']-$qty)throw new Exception('Unexpected reclassification totals; no changes were posted.');
 audit('Return damaged stock to Sellable','Non-Sellable','NS-'.$r['id'],json_encode(['batch_id'=>$batchId,'completion_id'=>$completion,'destination'=>$destination,'qty'=>$qty,'sellable_before'=>$before['current'],'sellable_after'=>$after['current'],'non_sellable_before'=>$before['nonsellable'],'non_sellable_after'=>$after['nonsellable'],'physical_delta'=>0]));return ['source_id'=>(int)$r['id'],'release_id'=>$release,'inflow_id'=>$inflow,'completion_id'=>$completion,'qty'=>$qty,'destination'=>$destination,'physical_delta'=>0];
}
